alter table public.admin_notifications add column if not exists category text not null default 'sistema';
alter table public.admin_notifications add column if not exists action_url text;
alter table public.admin_notifications add column if not exists event_key text;
create unique index if not exists admin_notifications_event_key_unique on public.admin_notifications(event_key) where event_key is not null;
create table if not exists public.admin_notification_reads(notification_id bigint not null references public.admin_notifications(id) on delete cascade,admin_user_id uuid not null references auth.users(id) on delete cascade,read_at timestamptz not null default now(),primary key(notification_id,admin_user_id));
alter table public.admin_notification_reads enable row level security;
drop policy if exists "Admins manage own notification reads" on public.admin_notification_reads;
create policy "Admins manage own notification reads" on public.admin_notification_reads for all to authenticated using(public.is_admin() and admin_user_id=auth.uid()) with check(public.is_admin() and admin_user_id=auth.uid());
create or replace function public.get_admin_notification_center(page_size integer default 20,page_offset integer default 0) returns jsonb language plpgsql security definer set search_path=public as $$ declare result jsonb; begin if not public.is_admin() then raise exception 'Acesso negado'; end if; select jsonb_build_object('unread_count',(select count(*) from public.admin_notifications n where not exists(select 1 from public.admin_notification_reads r where r.notification_id=n.id and r.admin_user_id=auth.uid())),'items',coalesce(jsonb_agg(to_jsonb(x) order by x.created_at desc),'[]'::jsonb)) into result from (select n.id,n.appointment_id,n.type,n.title,n.message,n.category,n.action_url,n.created_at,(r.read_at is not null) is_read from public.admin_notifications n left join public.admin_notification_reads r on r.notification_id=n.id and r.admin_user_id=auth.uid() order by n.created_at desc limit greatest(1,least(page_size,50)) offset greatest(page_offset,0)) x; return result; end $$;
create or replace function public.mark_admin_notification_read(target_id bigint default null) returns void language plpgsql security definer set search_path=public as $$ begin if not public.is_admin() then raise exception 'Acesso negado'; end if; insert into public.admin_notification_reads(notification_id,admin_user_id) select id,auth.uid() from public.admin_notifications where target_id is null or id=target_id on conflict do nothing; end $$;
revoke all on function public.get_admin_notification_center(integer,integer) from public; revoke all on function public.mark_admin_notification_read(bigint) from public;
grant execute on function public.get_admin_notification_center(integer,integer) to authenticated; grant execute on function public.mark_admin_notification_read(bigint) to authenticated;
update public.admin_notifications set category=case when type ilike '%payment%' then 'pagamento' when type ilike '%cancel%' then 'cancelamento' when type ilike '%resched%' then 'remarcação' when type ilike '%fit%' or type ilike '%booking%' then 'encaixe' when type ilike '%schedule%' then 'agenda mensal' else 'agendamento' end,action_url=case when type ilike '%payment%' then '/admin/solicitacoes?tab=pagamentos&request='||appointment_id when type ilike '%cancel%' then '/admin/solicitacoes?tab=cancelamentos&request='||appointment_id when type ilike '%schedule%' then '/admin#monthly-schedule' else '/admin/agenda' end where action_url is null;
alter table public.appointments add column if not exists completed_at timestamptz;
alter table public.appointments add column if not exists completed_by uuid references auth.users(id) on delete set null;
alter table public.appointments add column if not exists review_email_sent_at timestamptz;
insert into public.notification_preferences(id,email_enabled,priority) values('post_service',true,'normal') on conflict(id) do nothing;
insert into public.email_templates(id,subject,title,subtitle,body,signature,button_text,button_url,required_variables) values('post_service','Obrigada pela confiança! 🤎','Obrigada pela confiança! 🤎','Esperamos que você tenha aproveitado seu momento de cuidado.','<p>Olá {{customer_name}}, foi um prazer cuidar de você.</p>','Thaís Santos Beauty Studio<br>Cuidando da sua beleza com carinho. 🤎','Avaliar atendimento','{{review_url}}',array['{{customer_name}}','{{review_url}}']) on conflict(id) do update set subject=excluded.subject,title=excluded.title,subtitle=excluded.subtitle,body=excluded.body,button_text=excluded.button_text,button_url=excluded.button_url,required_variables=excluded.required_variables,updated_at=now();
create or replace function public.prepare_post_service_emails() returns void language plpgsql security definer set search_path=public as $$ declare a record; review_url text; begin select nullif(trim(public_data->>'google_review_url'),'') into review_url from public.studio_settings where id='main'; for a in select * from public.appointments where status='concluido' and review_email_sent_at is null and completed_at is not null and completed_at<=now()-interval '2 hours' loop perform public.enqueue_automation_email(a.email,'post_service','post_service','post-service:'||a.id,jsonb_build_object('customer_name',a.customer_name,'review_url',coalesce(review_url,'')),jsonb_build_object('appointment_id',a.id,'kind','post_service')); end loop; end $$;
create or replace function public.complete_automation_email(job_id bigint,was_sent boolean,error_text text default null) returns void language plpgsql security definer set search_path=public as $$ declare job public.automation_email_outbox%rowtype; begin select * into job from public.automation_email_outbox where id=job_id for update; if not found then return; end if; if was_sent then update public.automation_email_outbox set status='sent',sent_at=now(),last_error=null,updated_at=now() where id=job_id; if job.metadata->>'kind'='reminder_24h' then update public.appointments set reminder_sent_at=now() where id=(job.metadata->>'appointment_id')::uuid; end if; if job.metadata->>'kind'='post_service' then update public.appointments set review_email_sent_at=now() where id=(job.metadata->>'appointment_id')::uuid; end if; if job.metadata->>'kind'='promotion' then insert into public.promotion_email_history(promotion_id,customer_id,recipient,outbox_id) values((job.metadata->>'promotion_id')::uuid,(job.metadata->>'customer_id')::uuid,job.recipient,job.id) on conflict do nothing; end if; elsif error_text='disabled' then update public.automation_email_outbox set status='skipped',last_error=error_text,updated_at=now() where id=job_id; else update public.automation_email_outbox set status=case when attempts>=5 then 'failed' else 'pending' end,last_error=left(error_text,1000),next_attempt_at=now()+make_interval(mins=>least(60,attempts*10)),updated_at=now() where id=job_id; end if; end $$;
do $$ begin if exists(select 1 from pg_available_extensions where name='pg_cron') then create extension if not exists pg_cron; if not exists(select 1 from cron.job where jobname='beautyflow-post-service-preparation') then perform cron.schedule('beautyflow-post-service-preparation','20 * * * *','select public.prepare_post_service_emails();'); end if; end if; exception when others then raise notice 'Job pós-atendimento não pôde ser criado: %',sqlerrm; end $$;

