create or replace function public.notify_admin_domain_events() returns trigger language plpgsql security definer set search_path=public as $$ declare key text; category_value text; title_value text; message_value text; url_value text; begin
  if tg_table_name='appointments' then
    if tg_op='INSERT' then key:='appointment-created:'||new.id;category_value:='agendamento';title_value:='Novo agendamento';message_value:=new.customer_name;url_value:='/admin/agenda?date='||new.appointment_date;
    elsif new.payment_status is distinct from old.payment_status and new.payment_status in('confirmado','recusado') then key:='payment-status:'||new.id||':'||new.payment_status;category_value:='pagamento';title_value:=case when new.payment_status='confirmado' then 'Pagamento aprovado' else 'Pagamento recusado' end;message_value:=new.customer_name;url_value:='/admin/solicitacoes?tab=pagamentos&request='||new.id;
    elsif new.status is distinct from old.status and new.status='cancelado' then key:='appointment-cancelled:'||new.id;category_value:='cancelamento';title_value:='Um horário foi cancelado';message_value:=new.customer_name;url_value:='/admin/solicitacoes?tab=cancelamentos&request='||new.id; perform public.enqueue_automation_email('admin@invalid.local','admin_cancellation','admin_cancellation','admin-cancellation:'||new.id,jsonb_build_object('customer_name',new.customer_name,'appointment_date',to_char(new.appointment_date,'DD/MM/YYYY'),'appointment_time',left(new.appointment_time,5),'request_id',new.id),jsonb_build_object('requires_admin_email',true,'appointment_id',new.id)); if coalesce(new.cancelled_by,'') in ('cliente_area','cliente_link_email') then return new; end if;
    else return new; end if;
  elsif tg_table_name='booking_requests' then key:='fit:'||new.id||':'||new.status;category_value:='encaixe';title_value:=case when tg_op='INSERT' then 'Novo pedido de encaixe' when new.status='expirado' then 'Proposta de encaixe expirada' else 'Encaixe atualizado' end;message_value:=new.customer_name;url_value:='/admin/solicitacoes?tab=encaixes&request='||new.id; if tg_op='INSERT' then perform public.enqueue_automation_email('admin@invalid.local','admin_fit','admin_fit','admin-fit:'||new.id,jsonb_build_object('customer_name',new.customer_name,'request_id',new.id),jsonb_build_object('requires_admin_email',true)); end if;
  else key:='reschedule:'||new.id||':'||new.status;category_value:='remarcação';title_value:=case when tg_op='INSERT' then 'Novo pedido de remarcação' else 'Remarcação atualizada' end;message_value:=coalesce((select customer_name from public.appointments where id=new.appointment_id),'Cliente');url_value:='/admin/solicitacoes?tab=remarcacoes&request='||new.id; if tg_op='INSERT' then perform public.enqueue_automation_email('admin@invalid.local','admin_reschedule','admin_reschedule','admin-reschedule:'||new.id,jsonb_build_object('customer_name',message_value,'request_id',new.id),jsonb_build_object('requires_admin_email',true)); end if; end if;
  insert into public.admin_notifications(appointment_id,type,title,message,category,action_url,event_key) values(coalesce(new.id::text,null),category_value,title_value,message_value,category_value,url_value,key) on conflict(event_key) where event_key is not null do nothing; return new;
end $$;
drop trigger if exists notify_admin_appointment_events on public.appointments; create trigger notify_admin_appointment_events after insert or update of status,payment_status on public.appointments for each row execute function public.notify_admin_domain_events();
-- Encaixes e remarcações já geram notificações nas RPCs de domínio aplicadas.
-- Não adicionamos triggers paralelos para evitar dois registros do mesmo evento.

create or replace function public.record_appointment_completion() returns trigger language plpgsql security definer set search_path=public as $$ begin
  if new.status='concluido' and old.status is distinct from new.status then
    new.completed_at:=coalesce(new.completed_at,now()); new.completed_by:=coalesce(new.completed_by,auth.uid());
    insert into public.request_activity(request_type,request_id,action,description,performed_by)
    values('agendamento',new.id::text,'concluido','Atendimento marcado como concluído.',auth.uid());
  end if; return new;
end $$;
drop trigger if exists record_appointment_completion_trigger on public.appointments;
create trigger record_appointment_completion_trigger before update of status on public.appointments for each row execute function public.record_appointment_completion();
